library(shiny)

DATA_FILE <- "supervisors.csv"

# Skip the junk first row, so row two becomes the header
supervisors <- read.csv(DATA_FILE, skip = 1, stringsAsFactors = FALSE, check.names = FALSE)
names(supervisors) <- trimws(names(supervisors))
supervisors[is.na(supervisors)] <- ""

# Map the column names to the fields the app uses
supervisors$name         <- trimws(supervisors$Title)
supervisors$profile_url  <- trimws(supervisors$Link)
supervisors$interests    <- supervisors[["General description"]]
supervisors$projects     <- supervisors[["Projects I have supervised in the past"]]
supervisors$publications <- supervisors[["Relevant publications"]]

# The Tags column looks like ["Quantative", "Climate"], so strip the brackets and quotes
parse_tags <- function(x) {
  x <- gsub("\\[|\\]|\"", "", x)
  tags <- trimws(strsplit(x, ",")[[1]])
  tags[nzchar(tags)]
}

supervisors$tags_clean <- vapply(supervisors$Tags, function(x) {
  paste(parse_tags(x), collapse = "; ")
}, character(1))

all_tags <- sort(unique(unlist(lapply(supervisors$Tags, parse_tags))))

ui <- fluidPage(
  tags$head(tags$style(HTML("
    .tile { border: 1px solid #ccc; border-radius: 8px; margin-bottom: 12px; background: #fff; }
    .tile summary { list-style: none; padding: 14px 16px; cursor: pointer; }
    .tile summary::-webkit-details-marker { display: none; }
    .tile summary:hover { background: #f2f6fb; }
    .tile[open] summary { border-bottom: 1px solid #ccc; }
    .tile-body { padding: 12px 16px; }
    .tile h4 { margin-top: 0; margin-bottom: 6px; }
    .hint { color: #2a6ebb; font-weight: bold; font-size: 0.9em; }
    details[open] .hint { display: none; }
  "))),
  titlePanel("Psychology dissertation supervisors"),
  sidebarLayout(
    sidebarPanel(
      textInput("search", "Search by keyword", placeholder = "e.g. attention"),
      selectizeInput(
        "tags", "Filter by tags",
        choices = all_tags,
        multiple = TRUE,
        options = list(placeholder = "Start typing a tag")
      ),
      helpText("Shows only supervisors who match every selected tag.")
    ),
    mainPanel(
      uiOutput("results")
    )
  )
)

server <- function(input, output, session) {
  
  filtered <- reactive({
    df <- supervisors
    
    # Keyword match across name, interests, projects, publications and tags
    if (nzchar(input$search)) {
      keyword <- tolower(input$search)
      text <- tolower(paste(df$name, df$interests, df$projects,
                            df$publications, df$tags_clean))
      df <- df[grepl(keyword, text, fixed = TRUE), , drop = FALSE]
    }
    
    # Tag match: keep rows that have every selected tag
    if (length(input$tags) > 0) {
      keep <- vapply(df$tags_clean, function(t) {
        all(input$tags %in% strsplit(t, "; ")[[1]])
      }, logical(1))
      df <- df[keep, , drop = FALSE]
    }
    
    df
  })
  
  output$results <- renderUI({
    df <- filtered()
    if (nrow(df) == 0) {
      return(p("No supervisors match all of your selected tags. Try removing one."))
    }
    lapply(seq_len(nrow(df)), function(i) {
      
      name_tag <- if (nzchar(df$profile_url[i])) {
        a(df$name[i], href = df$profile_url[i], target = "_blank",
          onclick = "event.stopPropagation();")
      } else {
        df$name[i]
      }
      
      tags$details(
        class = "tile",
        tags$summary(
          h4(name_tag),
          markdown(df$interests[i]),
          p(tags$small(df$tags_clean[i])),
          tags$span(class = "hint", "Click to see projects and publications \u25BE")
        ),
        tags$div(
          class = "tile-body",
          tags$h5("Projects supervised"),
          markdown(df$projects[i]),
          tags$h5("Relevant publications"),
          markdown(df$publications[i])
        )
      )
    })
  })
}

shinyApp(ui, server)
